function sizeRangeFor(name, rarity, archetype) {
  const lower = name.toLowerCase();
  // Kraken is a giant legendary cephalopod, not an ordinary octopus-sized catch.
  // These are physical specimen ranges; the shared rendering/camera pipeline remains in charge.
  if (lower === 'kraken') return [[180, 600], [2000, 50000]];
  if (/\b(blue whale|humpback whale|sperm whale|leviathan)\b/.test(lower)) return [[180, 900], [3000, 180000]];
  if (/\bwhale shark\b/.test(lower)) return [[180, 480], [500, 40000]];
  if (/\b(great white shark|hammerhead shark)\b/.test(lower)) return [[96, 240], [180, 5000]];
  if (/\bocean sunfish\b/.test(lower)) return [[40, 132], [40, 5000]];
  if (/\bblue marlin\b/.test(lower)) return [[72, 168], [80, 1800]];
  if (/\barapaima\b/.test(lower)) return [[48, 132], [20, 400]];
  if (/\bbeluga sturgeon\b/.test(lower)) return [[60, 240], [80, 2500]];
  if (/\bgiant squid\b/.test(lower)) return [[60, 520], [50, 1500]];
  if (/\bcoelacanth\b/.test(lower)) return [[24, 79], [5, 200]];
  if (/\bgiant clam\b/.test(lower)) return [[12, 60], [1, 400]];
  if (/\banglerfish\b/.test(lower)) return [[6, 40], [.5, 25]];
  if (/\bseahorse\b/.test(lower)) return [[2, 8], [.02, .4]];
  if (/\bpenguin\b/.test(lower)) return [[18, 48], [2, 80]];
  if (/\b(orca|narwhal|beluga whale)\b/.test(lower)) return [[110, 300], [600, 16000]];
  if (/\b(dolphin|porpoise)\b/.test(lower)) return [[48, 144], [50, 1200]];
  if (archetype === 'pinniped') return lower.includes('walrus') ? [[72, 150], [700, 3200]] : [[36, 108], [45, 900]];
  if (archetype === 'sirenian') return [[70, 150], [300, 2500]];
  if (['mammal', 'rodent', 'otter', 'beaver', 'platypus'].includes(archetype)) {
    if (lower.includes('capybara')) return [[30, 55], [55, 180]];
    if (lower.includes('beaver') || lower.includes('giant otter')) return [[28, 60], [18, 100]];
    if (lower.includes('otter')) return [[22, 50], [8, 70]];
    if (lower.includes('platypus')) return [[15, 24], [1.5, 5.5]];
    return [[5, 32], [.08, 35]];
  }
  if (archetype === 'waterhorse') return [[42, 100], [40, 900]];
  if (archetype === 'dragon') return [[60, 360], [20, 3500]];
  if (archetype === 'serpent') return [[60, 360], [20, 3500]];
  if (archetype === 'plesiosaur') return [[90, 300], [300, 6000]];
  if (archetype === 'turtle') return (lower.includes('leatherback') || lower.includes('aspidochelone')) ? [[48, 120], [120, 2200]] : [[6, 48], [1, 220]];
  if (archetype === 'frog') return [[3, 9], [.1, 2.2]];
  if (archetype === 'starfish' || archetype === 'urchin') return [[1.5, 16], [.02, 5]];
  if (archetype === 'nautilus') return [[4, 12], [.2, 4]];
  if (/(shark|ray|skate|sturgeon|paddlefish)/.test(lower)) return [[24, 72], [7, 95]];
  if (/(eel|lamprey|gar|pike|salmon)/.test(lower)) return [[12, 42], [1, 28]];
  if (/(crab|lobster|octopus|squid|cuttlefish)/.test(lower)) return [[5, 28], [.25, 22]];
  if (/(shrimp|snail|mussel|limpet|scallop|beetle|boatman|jelly)/.test(lower)) return [[1.5, 9], [.02, 2.2]];
  const rarityScale = rarity === 'Legendary' ? 1.35 : rarity === 'Rare' ? 1.15 : 1;
  return [[4, Math.round(18 * rarityScale)], [.08, Math.round(6 * rarityScale * 10) / 10]];
}


const INSTRUMENTS = Object.freeze([
  'kalimba', 'marimba', 'xylophone', 'mandolin', 'flute', 'ocarina', 'oboe',
  'bassoon', 'clarinet', 'harp', 'handpan', 'guitar', 'tuba', 'saxophone',
  'violin_arco', 'cello_arco', 'upright_bass_pizz', 'glockenspiel'
]);

function definition(name, habitat, index, exclusive = false) {
  const rarity = RARITY_BY_NAME[name];
  const authoredSong = AUTHORED_SONGS[name];
  const archetype = archetypeFor(name);
  const [length, weight] = sizeRangeFor(name, rarity, archetype);
  const hue = ((index * 47) % 360) * Math.PI / 180;
  const color = (offset) => [
    .48 + Math.sin(hue + offset) * .22,
    .5 + Math.sin(hue + offset + 2.1) * .2,
    .5 + Math.sin(hue + offset + 4.2) * .2
  ].map((value) => Math.max(.12, Math.min(.9, value)));
  return Object.freeze({
    id: slug(name), name, rarity,
    catchWeight: rarity === 'Common' ? 12 : rarity === 'Uncommon' ? 8 : rarity === 'Rare' ? 4 : 1.8,
    length, weight, archetype, colors: [color(0), color(1.35)],
    instrument: INSTRUMENTS[index % INSTRUMENTS.length],
    root: 42 + (index * 5) % 29,
    bpm: [...authoredSong.bpm],
    motif: authoredSong.motif,
    difficulty: rarity === 'Common' ? .18 : rarity === 'Uncommon' ? .4 : rarity === 'Rare' ? .64 : .84,
    flavor: exclusive
      ? `A local species known only from ${habitat.exclusiveWaterId.replaceAll('-', ' ')}.`
      : 'A persistent mountain-water resident whose range follows its preferred habitat.',
    habitat: Object.freeze({
      ...habitat,
      preferredTheme: habitat.preferredTheme ?? ALL_THEMES[index % ALL_THEMES.length],
      exclusive: Boolean(exclusive)
    })
  });
}

const exclusiveDefinitions = WATER_EXCLUSIVES.flatMap(([waterId, tier, salinity, waterType, names]) => (
  names.map((name) => ({ name, habitat: {
    salinity, tiers: [tier], waterTypes: [waterType], themes: ALL_THEMES,
    exclusiveWaterId: waterId
  } }))
));

const sharedDefinitions = SHARED_SPECIES.map((entry) => ({ name: entry.name, habitat: { ...entry.habitat } }));

export const EXPANDED_SPECIES_DEFINITIONS = Object.freeze([
  ...exclusiveDefinitions.map((entry, index) => definition(entry.name, entry.habitat, index, true)),
  ...sharedDefinitions.map((entry, index) => definition(entry.name, entry.habitat, index + exclusiveDefinitions.length, false))
]);

export const EXPANSION_COUNTS = Object.freeze({
  exclusive: exclusiveDefinitions.length,
  shared: sharedDefinitions.length,
  total: exclusiveDefinitions.length + sharedDefinitions.length
});
